d representation."}, {"sourceSlug": "yemen", "sourceName": "Yemen", "verb": "CONTAINS", "targetSlug": "houthis", "targetName": "Houthis", "context": "The Houthis operate primarily within Yemen, especially in the northern regions, impacting its political and social structures."}], "places": [{"name": "Saada, Yemen", "role": "Birthplace"}, {"name": "Sana'a, Yemen", "role": "Major conflict site"}, {"name": "Marib, Yemen", "role": "Strategic battleground"}], "texts": [{"title": "Wikipedia: Houthis", "type": "Reference article", "slug": "houthis"}], "externalLinks": ["https://www.wikidata.org/wiki/Q3042087", "https://en.wikipedia.org/wiki/Houthis"], "tags": ["Yemen", "armed organization", "Asia", "Military & Defense Organizations", "cause-and-effect"], "thumbnailUrl": "", "quote": "", "legacySummary": "Houthis left a notable mark on Contemporary history, documented across 83 Wikipedia editions worldwide. Key lasting impacts include: Shaped institutional landscape and community development. Their legacy is studied through the lens of historical causation.", "historicalSignificance": {"significanceScore": 7, "significanceNarrative": "The Houthis have played a critical role in reshaping Yemen's political landscape and have significantly influenced regional geopolitics, attracting international attention and intervention due to the ongoing conflict.", "significanceCategory": "regional"}, "_editLog": [{"timestamp": "2026-06-14T06:14:44Z", "editorId": "gpt-4o-mini·cloud·GH#27490245124", "field": "summary", "oldValue": "Yemeni islamist organization. Houthis is a armed organization in Saada, established in 1994. Holds notable historical significance, documented across 83 language editions of Wikipedia. Relevant to cause-and-effect analysis.", "newValue": "The Houthis, formally known as Ansar Allah, are a prominent Yemeni Islamist movement that originated in the northern region of Saada in 1994, led by Hussein Badreddin al-Houthi until his death in 2004. This group emerged from the Zaidi Shia sect and has significantly influenced the socio-political landscape of Yemen, particularly during the Yemeni Civil War that escalated in 2015. Their actions are not only pivotal in Yemen but have also impacted regional dynamics in West Asia, drawing in various international actors and affecting global oil markets due to the strategic location of Yemen.

